class Invoice {
  constructor(private lines: Line[], private region: Region) {}

  // shared by total() AND the PDF
  private taxedSubtotal(): number {
    const subtotal = this.lines.reduce((s, l) => s + l.amount, 0);
    return subtotal * rateFor(this.region); // Finance owns the tax rule
  }

  total(): number { return this.taxedSubtotal(); }          // Finance
  renderPdf(): Buffer { return pdf(this.taxedSubtotal()); }  // owned by the design/locale team
  save(): void { db.invoices.insert(this.toRow()); }         // owned by the DBA
}
